INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15601, 'Proverbs 7:14', 'Proverbs', 7, 14, '&nbsp;”نن ما کره د قربانۍ غوښه ده او ما خپل نذر پوره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15602, 'Proverbs 7:15', 'Proverbs', 7, 15, '&nbsp;نو زۀ بهر راووتلم چې تا سره مِلاو شم، ما ستا لټون کولو او تۀ راته مِلاو شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15603, 'Proverbs 7:16', 'Proverbs', 7, 16, '&nbsp;ما په خپل کټ باندې د مِصر رنګارنګ د لټې څادرونه اچولى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15604, 'Proverbs 7:17', 'Proverbs', 7, 17, '&nbsp;ما په خپل کټ باندې د مُر چيړ، عُود او دارچينۍ خوشبو لګولې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15605, 'Proverbs 7:18', 'Proverbs', 7, 18, '&nbsp;راځه چې تر سحره پورې په مينه کښې ډُوب شُو. او د يو بل د مينې نه خوند واخلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15606, 'Proverbs 7:19', 'Proverbs', 7, 19, '&nbsp;ځکه چې زما خاوند په کور کښې نشته. هغه په لرې سفر باندې تلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15607, 'Proverbs 7:20', 'Proverbs', 7, 20, '&nbsp;هغۀ خپل جيب د پېسو نه ډک کړے دے، او د دې مياشتې تر آخره به واپس نۀ راځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15608, 'Proverbs 7:21', 'Proverbs', 7, 21, '&nbsp;نو په نرمو خبرو سره يې هغه غلط کړو، او د هغې پستو خبرو وغلولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15609, 'Proverbs 7:22', 'Proverbs', 7, 22, '&nbsp;نو هغه سمدستى هغې پسې د يو داسې غوَيى په شان روان شو لکه چې حلالېدو له روان وى، لکه چې هوسۍ په دام کښې ونښلى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15610, 'Proverbs 7:23', 'Proverbs', 7, 23, '&nbsp;ترڅو چې يو غشے د هغۀ زړۀ غوڅ کړى. هغه د يو داسې مارغۀ په شان وو چې د دام طرف ته منډې وهى، هغۀ ته پته نۀ وى چې هغه به د ژوند نه لاس ووينځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15611, 'Proverbs 7:24', 'Proverbs', 7, 24, '&nbsp;نو بيا زما زامنو، ما ته غوږ ونيسئ، زۀ چې درته څۀ وايم نو هغې ته توجو وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15612, 'Proverbs 7:25', 'Proverbs', 7, 25, '&nbsp;خپل زړۀ ته اجازت مۀ ورکوه چې د داسې ښځې طرف ته مائل شى، او يا د هغې په غلطو لارو روان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15613, 'Proverbs 7:26', 'Proverbs', 7, 26, '&nbsp;هغه د ډېرو کسانو د تباهۍ سبب شوې ده او د بې‌شمېره کسانو د مرګ سبب شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15614, 'Proverbs 7:27', 'Proverbs', 7, 27, '&nbsp;د هغې کور د قبر طرف ته لار ده، او دا د مرګ دالان ته لارښودنه کول دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15615, 'Proverbs 8:1', 'Proverbs', 8, 1, '&nbsp;غوږ شئ. ولې پوهه آوازونه نۀ کوى څۀ؟ پوهې خپل آواز نۀ دے پورته کړے څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15616, 'Proverbs 8:2', 'Proverbs', 8, 2, '&nbsp;هغه په اوچتو ځايونو د لارې په خوا کښې، او چرته چې لارې په خپلو کښې ملاويږى ولاړه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15617, 'Proverbs 8:3', 'Proverbs', 8, 3, '&nbsp;هغه ښار ته د ننوتو او راوتو دروازو په خوا کښې ولاړه وى او په زوره چغې وهى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15618, 'Proverbs 8:4', 'Proverbs', 8, 4, '&nbsp;”اے خلقو زۀ تاسو ټولو ته آواز کوم، او په زمکه باندې ټولو انسانانو ته آواز کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15619, 'Proverbs 8:5', 'Proverbs', 8, 5, '&nbsp;اے ساده خلقو، احتياط زده کړئ، اے بې‌وقوفو. عقل حاصل کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15620, 'Proverbs 8:6', 'Proverbs', 8, 6, '&nbsp;غوږ شئ. ما سره ستاسو دپاره اعلىٰ خبرې دى، او زۀ چې شونډې پرانيزم نو هغه څۀ وايم څۀ چې صحيح وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15621, 'Proverbs 8:7', 'Proverbs', 8, 7, '&nbsp;زما خولۀ هغه څۀ وائى څۀ چې رښتيا وى، ځکه چې زما شونډې د دروغو نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15622, 'Proverbs 8:8', 'Proverbs', 8, 8, '&nbsp;زما د خولې ټولې خبرې صحيح دى، يو خبره يې هم کږه يا د دوکې نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15623, 'Proverbs 8:9', 'Proverbs', 8, 9, '&nbsp;هوښيار په دې پوهيږى چې زما ټولې خبرې ټيک دى، چا سره چې عِلم وى هغۀ ته پته وى چې دا صحيح دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15624, 'Proverbs 8:10', 'Proverbs', 8, 10, '&nbsp;د سپينو زرو په ځائ زما لارښودنې غوره کړئ، او د خالص سرو زرو نه عِلم خوښ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15625, 'Proverbs 8:11', 'Proverbs', 8, 11, '&nbsp;ځکه چې حِکمت د قيمتى کاڼو نه هم ګران دے، او ستا د خوښې يو څيز هم د دې برابر نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15626, 'Proverbs 8:12', 'Proverbs', 8, 12, '&nbsp;زۀ حِکمت د پوهې سره يو ځائ اوسېږم، او ما سره عِلم او تميز شته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15627, 'Proverbs 8:13', 'Proverbs', 8, 13, '&nbsp;د مالِک خُدائ نه ويرېدل دا دى چې د بدۍ نه نفرت وکړئ، زۀ د غرور، کبر او غلط چال چلن او بدو خبرو نه نفرت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15628, 'Proverbs 8:14', 'Proverbs', 8, 14, '&nbsp;ښې مشورې او تميز ورکول زما کار دے، زۀ پوهه او طاقت لرم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15629, 'Proverbs 8:15', 'Proverbs', 8, 15, '&nbsp;زما په وجه بادشاهان حکومت کوى او حکمرانان منصفانه قانون جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15630, 'Proverbs 8:16', 'Proverbs', 8, 16, '&nbsp;زما په وجه شهزادګان حکومت کوى، او ټول صادق حکمرانان څوک چې په زمکه حکومت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15631, 'Proverbs 8:17', 'Proverbs', 8, 17, '&nbsp;زۀ د هغه چا سره مينه کوم څوک چې ما سره مينه کوى، او څوک چې زما لټون کوى نو ما بيامومى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15632, 'Proverbs 8:18', 'Proverbs', 8, 18, '&nbsp;ما سره مال او عزت دے، تر ډېر وخته دولت او صداقت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15633, 'Proverbs 8:19', 'Proverbs', 8, 19, '&nbsp;زما مېوه د سوچه سرو زرو ‎‎‎‎نه ښۀ ده، او زما پېداوار د خالصو سپينو زرو نه بهتر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15634, 'Proverbs 8:20', 'Proverbs', 8, 20, '&nbsp;زۀ د صداقت په لاره روان يم، او د اِنصاف په لارو عمل کوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15635, 'Proverbs 8:21', 'Proverbs', 8, 21, '&nbsp;څوک چې ما سره مينه کوى په ميراث کښې ورته دولت ورکوم، او د هغوئ خزانې به ډکې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15636, 'Proverbs 8:22', 'Proverbs', 8, 22, '&nbsp;مالِک خُدائ د هر څۀ نه وړاندې چې نور څۀ پېدا کړى، د ټولو نه اول يې زۀ پېدا کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15637, 'Proverbs 8:23', 'Proverbs', 8, 23, '&nbsp;زۀ يې د ازل نه مقرر کړے وم، د دې نه مخکښې چې دُنيا لا پېدا شوې هم نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15638, 'Proverbs 8:24', 'Proverbs', 8, 24, '&nbsp;کله چې لا سمندر نۀ وو زۀ پېدا شوے وم، کله چې لا د چينو اوبۀ نۀ وې روانې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15639, 'Proverbs 8:25', 'Proverbs', 8, 25, '&nbsp;مخکښې د دې نه چې لا غرونه او غونډۍ په خپل ځائ نۀ وُو ولاړ زۀ پېدا شوے وم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15640, 'Proverbs 8:26', 'Proverbs', 8, 26, '&nbsp;د هغې نه وړاندې چې لا خُدائ پاک زمکه او د هغې پټى او لا نۀ يې د دُنيا خاوره پېدا کړې وه چې زۀ پېدا وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15641, 'Proverbs 8:27', 'Proverbs', 8, 27, '&nbsp;زۀ هلته وم هر کله چې هغۀ آسمان په خپل ځائ ودرولو، او کله چې يې د سمندر په مخ د فضا لهرونه خوارۀ کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15642, 'Proverbs 8:28', 'Proverbs', 8, 28, '&nbsp;کله چې هغۀ بره وريځ مقرر کړه او کله چې د سمندر د ډکولو دپاره چينې جوړې کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15643, 'Proverbs 8:29', 'Proverbs', 8, 29, '&nbsp;او کله چې هغۀ سمندر ته حد مقرر کړو، ترڅو چې اوبۀ د هغۀ د حُکم نه يو قدم هم زيات وانۀ خلى، او کله چې هغۀ د زمکې بنيادونه کېښودل نو زۀ هلته وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15644, 'Proverbs 8:30', 'Proverbs', 8, 30, '&nbsp;زۀ د هغۀ په څنګ کښې وم څوک چې د ټولو نه ښۀ ګلکار دے، زۀ هره ورځ د هغۀ د خوشحالۍ سبب وم، او ما تل د هغۀ په حضور کښې خوشحالى کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15645, 'Proverbs 8:31', 'Proverbs', 8, 31, '&nbsp;زۀ د هغۀ په ټوله دُنيا کښې ډېره خوشحاله وم، او د انسانانو نه مې خوشحالى حاصلوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15646, 'Proverbs 8:32', 'Proverbs', 8, 32, '&nbsp;نو اوس اے زما زامنو، ما ته غوږ ونيسئ، مبارک دى هغوئ څوک چې زما په لارو عمل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15647, 'Proverbs 8:33', 'Proverbs', 8, 33, '&nbsp;زما تعليماتو ته غوږ شئ او هوښيار شئ، دا مۀ نظر انداز کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15648, 'Proverbs 8:34', 'Proverbs', 8, 34, '&nbsp;مبارک دے هغه څوک چې ما ته غوږ نيسى، چې روزانه زما په دروازه کښې ولاړ وى، او زما په دروازه کښې انتظار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15649, 'Proverbs 8:35', 'Proverbs', 8, 35, '&nbsp;ځکه چې څوک ما ومومى نو هغه ژوند مومى، او د مالِک خُدائ رضا حاصلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15650, 'Proverbs 8:36', 'Proverbs', 8, 36, '&nbsp;خو څوک چې ما نۀ حاصلوى خپل ځان ته نقصان ورکوى، هر څوک چې زما نه نفرت کوى نو هغه د مرګ سره مينه کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15651, 'Proverbs 9:1', 'Proverbs', 9, 1, '&nbsp;پوهې خپل کور جوړ کړے دے، او خپل ځان دپاره يې اووۀ ستنې تراشلې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15652, 'Proverbs 9:2', 'Proverbs', 9, 2, '&nbsp;هغې خپله غوښه تياره کړې ده او مے يې يو ځائ کړى دى، او دسترخوان يې هم خور کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15653, 'Proverbs 9:3', 'Proverbs', 9, 3, '&nbsp;هغې خپله وينځه ورولېږله او هغه د ښار د اوچتو ځايونو نه آوازونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15654, 'Proverbs 9:4', 'Proverbs', 9, 4, '&nbsp;”څوک چې ساده ګان وى هغوئ ټول دې دلته راشى.“ او هغه هغوئ ته وينا کوى څوک چې ناپوهه وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15655, 'Proverbs 9:5', 'Proverbs', 9, 5, '&nbsp;”راشئ، زما خوراک وخورئ او هغه مے وڅښئ کوم چې ما ګډ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15656, 'Proverbs 9:6', 'Proverbs', 9, 6, '&nbsp;خپله ساده لار پرېږدئ نو تاسو به ژوندى پاتې شئ، او د پوهې په لار تلل وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15657, 'Proverbs 9:7', 'Proverbs', 9, 7, '&nbsp;هر څوک چې د مسخره کوونکى اصلاح کوى نو د خپلې بې‌عزتۍ دعوت ورکوى، هر څوک چې د شرير د شرارت نه ممانعت کوى، نو خپل ځان به سپک کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15658, 'Proverbs 9:8', 'Proverbs', 9, 8, '&nbsp;نو تۀ کله هم د مسخره کوونکى رټنه مۀ کوه هغه به ستا نه نفرت کوى، هوښيار ته تنبيه ورکړه هغه به تا سره مينه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15659, 'Proverbs 9:9', 'Proverbs', 9, 9, '&nbsp;هوښيار ته لارښودنه وکړه نو هغه به نور هم هوښيار شى، صادق ته تعليم ورکړه نو هغه به د دې نه نور تعليم هم زده کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15660, 'Proverbs 9:10', 'Proverbs', 9, 10, '&nbsp;د مالِک خُدائ يره د حِکمت شروع ده، د مقدس ذات پېژندګلو د پوهې اصليت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15661, 'Proverbs 9:11', 'Proverbs', 9, 11, '&nbsp;نو زما په وجه به ستا د ژوند ورځې ډيرې شى، او ستا د عمر سره به نور کلونه سېوا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15662, 'Proverbs 9:12', 'Proverbs', 9, 12, '&nbsp;کۀ چرې تۀ حِکمت لرې نو هغه به تا له فائده درکړى، او کۀ تۀ مسخره کوونکے يې نو صرف تا ته به د هغې نقصان مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15663, 'Proverbs 9:13', 'Proverbs', 9, 13, '&nbsp;کم عقله ښځه سرتېزه وى، هغه بې‌ادبه او بې‌علمه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15664, 'Proverbs 9:14', 'Proverbs', 9, 14, '&nbsp;د هغې کور د ښار په لوړ ځائ کښې دے. د دروازې سره ناسته وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15665, 'Proverbs 9:15', 'Proverbs', 9, 15, '&nbsp;او څوک چې په خپله لاره سيدها تېريږى نو هغوئ ته آوازونه ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15666, 'Proverbs 9:16', 'Proverbs', 9, 16, '&nbsp;”اے ساده خلقو ټول دلته راشئ.“ هغه ټولو ناپوهو ته وينا کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15667, 'Proverbs 9:17', 'Proverbs', 9, 17, '&nbsp;”د غلا اوبۀ خوږې وى، هغه روټۍ چې په پټه خوړلے شى خوندوره وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15668, 'Proverbs 9:18', 'Proverbs', 9, 18, '&nbsp;خو دوئ لږ هم په دې نۀ پوهيږى چې د هغې ښځې په کور کښې صرف مرګ دے، څوک هم چې د هغې په کور کښې مېلمانۀ شوى دى نو هغوئ اوس د تورو خاورو لاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15669, 'Proverbs 10:1', 'Proverbs', 10, 1, '&nbsp;دا د سليمان متلونه دى، يو هوښيار زوئ خپل پلار له خوشحالى ورکوى، خو کم عقل زوئ خپلې مور له غم ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15670, 'Proverbs 10:2', 'Proverbs', 10, 2, '&nbsp;د حرام مال دولت هيڅ اهميت نشته، خو صداقت د مرګ نه خلاصون ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15671, 'Proverbs 10:3', 'Proverbs', 10, 3, '&nbsp;مالِک خُدائ صادق اوږى کېدو ته نۀ پرېږدى، خو د بدکارانو ارمان رد کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15672, 'Proverbs 10:4', 'Proverbs', 10, 4, '&nbsp;ناراسته لاسونه يو انسان غريبوى، خو محنتى لاسونه انسان مالداره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15673, 'Proverbs 10:5', 'Proverbs', 10, 5, '&nbsp;څوک چې په ګرمۍ کښې فصل راټولوى هغه هوښيار زوئ دے، خو هغه زوئ څوک چې د لو په وخت کښې خوب کوى د شرم باعث دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15674, 'Proverbs 10:6', 'Proverbs', 10, 6, '&nbsp;برکت د صادق د سر تاج دے، خو بدعمله په خپلو چالاکه خبرو سره خپل شرارت پټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15675, 'Proverbs 10:7', 'Proverbs', 10, 7, '&nbsp;د نېکانو يادول د برکت سبب ګرځى، خو د بد کاره نوم به فنا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15676, 'Proverbs 10:8', 'Proverbs', 10, 8, '&nbsp;هوښياران په نصيحت خوشحاليږى، خو بې‌وقوفه کړتن به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15677, 'Proverbs 10:9', 'Proverbs', 10, 9, '&nbsp;نېک انسان به په امن کښې ګرځى، خو هغه څوک چې کږې لارې اختياروى، د هغۀ کارونو نه به خلق خبر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15678, 'Proverbs 10:10', 'Proverbs', 10, 10, '&nbsp;هغه څوک چې په ټګۍ سره سترګې وهى نو د تکليف باعث کيږى، او په بې‌فکره خبرو سره به کم عقل تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15679, 'Proverbs 10:11', 'Proverbs', 10, 11, '&nbsp;د صادق خولۀ د ژوند چينه ده، خو بدعمله په خپلو چالاکه خبرو سره خپل شرارت پټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15680, 'Proverbs 10:12', 'Proverbs', 10, 12, '&nbsp;نفرت شر جوړوى، خو مينه په ټولو بدو پرده اچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15681, 'Proverbs 10:13', 'Proverbs', 10, 13, '&nbsp;د هوښيار په شونډو کښې پوهه موندلے کيږى، خو د ناپوهه دپاره چوکه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15682, 'Proverbs 10:14', 'Proverbs', 10, 14, '&nbsp;هوښياران خپل عِلم ذخيره کوى، خو د کم عقل فضول خبرې تباهۍ ته دعوت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15683, 'Proverbs 10:15', 'Proverbs', 10, 15, '&nbsp;د مالداره مال دولت د هغۀ دپاره قلعه ده، خو غربت د غريب دپاره تباهى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15684, 'Proverbs 10:16', 'Proverbs', 10, 16, '&nbsp;د صادق ګټه هغۀ له ژوند ورکوى، خو د بدکاره ګټه هغه د ګناه طرف ته بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15685, 'Proverbs 10:17', 'Proverbs', 10, 17, '&nbsp;هغه څوک چې اصلاح قبلوى د ژوند په لاره ځى، خو هر هغه څوک چې اصلاح کول نۀ منى نو خپل ځان بې‌لارې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15686, 'Proverbs 10:18', 'Proverbs', 10, 18, '&nbsp;هغه څوک چې خپل نفرت پټوى نو هغه دروغژن دے. څوک چې د نورو غېبت کوى هغه کم عقل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15687, 'Proverbs 10:19', 'Proverbs', 10, 19, '&nbsp;هرکله چې خبرې ډيرې وى نو هلته ګناه هم موجوده وى، خو څوک چې خپله ژبه قابو ساتى هوښيار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15688, 'Proverbs 10:20', 'Proverbs', 10, 20, '&nbsp;د صادق ژبه خالص سپين زر وى، خو د بدکاره زړۀ بې‌اهميته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15689, 'Proverbs 10:21', 'Proverbs', 10, 21, '&nbsp;د صادق د خولې کلام ډېرو خلقو له فائده ورکوى، خو کم عقل د ناپوهۍ په وجه مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15690, 'Proverbs 10:22', 'Proverbs', 10, 22, '&nbsp;د مالِک خُدائ برکت انسان مالداره کوى، او په کښې هيڅ قسم غم نۀ سېوا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15691, 'Proverbs 10:23', 'Proverbs', 10, 23, '&nbsp;کم عقل د غلط کار نه خوند اخلى، خو هوښيار سړے د حِکمت نه خوند اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15692, 'Proverbs 10:24', 'Proverbs', 10, 24, '&nbsp;د کوم شى نه چې بدکاره يريږى نو هم هغه به يې راګېر کړى، خو صادق چې د کوم شى خواهش وکړى هغه به ورله ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15693, 'Proverbs 10:25', 'Proverbs', 10, 25, '&nbsp;هرکله چې طوفان راشى نو بدکاره جارُو کړى، خو صادق به د تل دپاره قائم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15694, 'Proverbs 10:26', 'Proverbs', 10, 26, '&nbsp;لکه څنګه چې سرکه غاښونه برېښوى او لوګے سترګې ترخوى، نو دغه شان ناراسته د خپل مالِک دپاره دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15695, 'Proverbs 10:27', 'Proverbs', 10, 27, '&nbsp;د مالِک خُدائ يره عمر اوږدوى، خو د شرير عمر به لنډ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15696, 'Proverbs 10:28', 'Proverbs', 10, 28, '&nbsp;د صادق اُميد خوشحالى ده، خو د بدکاره طمع به پوره نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15697, 'Proverbs 10:29', 'Proverbs', 10, 29, '&nbsp;د مالِک خُدائ لارې د صادقانو پناه ګاه وى، خو د هغه خلقو دپاره تباهى وى څوک چې بدکارونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15698, 'Proverbs 10:30', 'Proverbs', 10, 30, '&nbsp;صادق به کله هم د بېخ نه ختم نۀ شى، خو بدکاره به په زمکه پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15699, 'Proverbs 10:31', 'Proverbs', 10, 31, '&nbsp;د صادق د خولې نه د عقل او حِکمت خبرې راوځى، خو کږه ژبه به پرې کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15700, 'Proverbs 10:32', 'Proverbs', 10, 32, '&nbsp;د صادق شونډې په دې پوهيږى چې کومه خبره د منلو او په ځائ ده، خو د بدکاره د خولې نه صرف غلطې خبرې راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');